<template>
  <div class="page">
    <div class="shop-manage__table-wrap">
      <div class="panel">
        <div class="panel__header">
          <div class="panel__title">
            <h3>门店管理</h3>
          </div>
        </div>
        <div class="panel__table-wrap">
          <el-table ref="tableRef" :data="pagedData" style="width: 100%" :header-cell-style="{ textAlign: 'left' }" :cell-style="{ textAlign: 'left' }">
            <el-table-column prop="name" label="门店名称" min-width="180" />
            <el-table-column prop="address" label="地址" min-width="240" />
            <el-table-column prop="phone" label="联系电话" min-width="140" />
            <el-table-column prop="manager" label="店长" min-width="110" />
            <el-table-column prop="tag" label="状态" min-width="100">
              <template #default="scope">
                <el-tag :type="tagType(scope.row.tag)" disable-transitions>{{ scope.row.tag }}</el-tag>
              </template>
            </el-table-column>
            <el-table-column prop="createtime" label="开业时间" min-width="180" />
            <el-table-column label="操作" min-width="140">
              <template #default="scope">
                <el-button
                  size="small"
                  :type="scope.row.tag === '停业' ? 'success' : 'danger'"
                  @click="handleToggle(scope.row.name)"
                >
                  {{ scope.row.tag === '停业' ? '营业' : '停业' }}
                </el-button>
              </template>
            </el-table-column>
          </el-table>
        </div>
      </div>
      <div class="shop-manage__pagination-wrap">
        <div class="totalnum">
          <h3>门店统计</h3>
          <p>当前共 {{ tableData.length }} 家门店</p>
        </div>
        <div class="example-pagination-block">
          <el-pagination
            layout="prev, pager, next"
            :total="tableData.length"
            :page-size="pageSize"
            :current-page="currentPage"
            @current-change="currentPage = $event"
          />
        </div>
      </div>
    </div>
  </div>
